<script setup lang="ts">
import {useEditorDraft} from './editorGuard';
import {computed,nextTick,ref} from 'vue';import {Plus,Upload,Download,Check,Trash2,ArrowRight,Building2,Network,FileSpreadsheet} from 'lucide-vue-next';
import {request,download} from './model';import type {State,Device} from './model';
const props=defineProps<{state:State;projectId:string;siteId?:string}>();
const emit=defineEmits<{saved:[state:State];refresh:[state:State];busy:[busy:boolean];finish:[target:'room'|'topology',projectId:string,siteId:string]}>();
type Row={templateId:string;moduleId:string;name:string;content:string;fileName:string};
const stage=ref(0),heading=ref<HTMLElement>(),mode=ref<'unified'|'modules'|'layout'>('unified'),showSample=ref(false);
const busy=ref(false),error=ref(''),fileNames=ref({unified:'',networks:'',links:''});
const form=ref({projectId:props.projectId,projectName:'',siteId:props.siteId||'',siteName:'',defaultTemplateId:props.state.templates[0]?.id||'',defaultModuleName:'',unifiedCSV:'',networksCSV:'',linksCSV:'',infer:false,allowNewModels:false,modules:[fresh(1)]});
function fresh(index=1):Row{return {templateId:props.state.templates[0]?.id||'',moduleId:'',name:'微模块 '+index,content:'',fileName:''}}
const rooms=computed(()=>props.state.sites.filter(s=>s.projectId===form.value.projectId));
const existingModules=computed(()=>props.state.modules.filter(m=>m.siteId===form.value.siteId));
function destinationChanged(){preview.value=null;form.value.defaultModuleName=existingModules.value[0]?.name||'微模块 1';for(const row of form.value.modules)row.moduleId=''}
const payload=computed(()=>({projectId:form.value.projectId,projectName:form.value.projectId?'':form.value.projectName.trim(),siteId:form.value.siteId,siteName:form.value.siteId?'':form.value.siteName.trim(),defaultTemplateId:form.value.defaultTemplateId,defaultModuleName:form.value.defaultModuleName,unifiedCSV:mode.value==='unified'?form.value.unifiedCSV:'',modules:mode.value!=='unified'?form.value.modules.map(({fileName,...rest})=>({...rest,content:mode.value==='layout'?'':rest.content})):[],networksCSV:form.value.networksCSV,linksCSV:form.value.linksCSV,infer:form.value.infer,allowNewModels:form.value.allowNewModels}));
const draft=useEditorDraft(()=>({form:form.value,mode:mode.value}),()=>busy.value);
const key=computed(()=>JSON.stringify(payload.value));
type Preview={revision:number;projectId:string;siteId:string;newModules:number;newModels:number;devices:number;placed:number;pending:number;networks:number;links:number;resolvedModules:{id:string;name:string;existing:boolean}[];warnings:string[];rows:{device:Device;reason:string;line:number}[];state:State};
const preview=ref<Preview|null>(null),previewKey=ref('');const validPreview=computed(()=>preview.value&&previewKey.value===key.value&&preview.value.revision===props.state.revision);
const done=ref<{projectId:string;siteId:string;siteName:string;devices:number;links:number;pending:number}|null>(null);
const canNext=computed(()=>(!!form.value.projectId||!!form.value.projectName.trim())&&(!!form.value.siteId||!!form.value.siteName.trim()));
const canPreview=computed(()=>canNext.value&&(mode.value!=='unified'||!!form.value.unifiedCSV.trim()));
const newLinks=computed(()=>preview.value?.state.links.filter(l=>!props.state.links.some(old=>old.id===l.id))||[]);
function exportLinks(){const cell=(v:unknown)=>{let text=String(v??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};const rows=newLinks.value.map(l=>[preview.value?.state.devices.find(d=>d.id===l.sourceId)?.name,preview.value?.state.devices.find(d=>d.id===l.targetId)?.name,l.sourcePort,l.targetPort,l.status].map(cell).join(','));download('初始化连接预览.csv','\ufeff端点A,端点B,端口A,端口B,状态\n'+rows.join('\n'),'text/csv')}
const changedNetworks=computed(()=>preview.value?.state.networks.filter(n=>JSON.stringify(props.state.networks.find(old=>old.id===n.id))!==JSON.stringify(n))||[]);
const destination=computed(()=>`${props.state.projects.find(p=>p.id===form.value.projectId)?.name||form.value.projectName} / ${rooms.value.find(r=>r.id===form.value.siteId)?.name||form.value.siteName}`);
const deviceTemplate='模块,型号,数量,名称,资产编号,网络\n';
const fullTemplate='模块,型号,数量,名称,资产编号,资产前缀,机柜,起始U,IP,SN,网络,设备角色,U高,布局模板,备注\n';
const networkTemplate='网络名称,上级网络,用途,VLAN,网段,网关\n';const linkTemplate='源资产编号,目标资产编号,源端口,目标端口,类型,速率,介质,网络,确认状态\n';
async function step(value:number){if(busy.value)return;stage.value=value;error.value='';await nextTick();heading.value?.focus();document.querySelector('.editor-page')?.scrollTo({top:0,behavior:'instant'})}
async function file(event:Event,kind:'unified'|'networks'|'links',row?:Row){const input=event.target as HTMLInputElement,f=input.files?.[0];if(!f)return;try{if(f.size>2*1024*1024)throw new Error('文件最大2MiB');const text=new TextDecoder('utf-8',{fatal:true}).decode(await f.arrayBuffer());if(row){row.content=text;row.fileName=f.name}else{form.value[kind==='unified'?'unifiedCSV':kind==='networks'?'networksCSV':'linksCSV']=text;fileNames.value[kind]=f.name};preview.value=null;error.value=''}catch(e){error.value=(e as Error).message||'请在Excel/WPS中另存为CSV UTF-8后重试'}input.value=''}
function example(){form.value.unifiedCSV='模块,型号,数量,名称,资产编号,资产前缀,网络\n示例计算模块,RZ2805-48YS8CQ,1,示例接入,DEMO-SW-01,,业务网\n示例计算模块,KunTai R722 K2,4,示例服务器,,DEMO-SRV,业务网\n';fileNames.value.unified='示例总清单.csv';preview.value=null;showSample.value=true}
async function inspect(){if(busy.value||!canPreview.value)return;busy.value=true;emit('busy',true);error.value='';const input=key.value;try{const p=await request<Preview>('/initialize/preview','POST',{...JSON.parse(input),revision:props.state.revision});if(input!==key.value){error.value='文件已变化，请重新预览';return}preview.value=p;previewKey.value=input;stage.value=2;await nextTick();heading.value?.focus();document.querySelector('.editor-page')?.scrollTo({top:0,behavior:'instant'})}catch(e){error.value=(e as Error).message;if((e as {status?:number}).status===409){try{emit('refresh',await request<State>('/state'))}catch{}preview.value=null}}finally{busy.value=false;emit('busy',false)}}
async function commit(){if(!validPreview.value||busy.value)return;busy.value=true;emit('busy',true);error.value='';try{const next=await request<State>('/initialize/commit','POST',{...JSON.parse(previewKey.value),revision:preview.value!.revision});const projectId=form.value.projectId||next.projects.find(p=>p.name===form.value.projectName.trim())!.id;const siteId=form.value.siteId||next.sites.find(r=>r.projectId===projectId&&r.name===form.value.siteName.trim())!.id;done.value={projectId,siteId,siteName:next.sites.find(r=>r.id===siteId)!.name,devices:preview.value!.devices,links:preview.value!.links,pending:preview.value!.pending};draft.accept();emit('saved',next);await nextTick();heading.value?.focus()}catch(e){error.value=(e as Error).message;preview.value=null;stage.value=1;if((e as {status?:number}).status===409){try{emit('refresh',await request<State>('/state'))}catch{}}}finally{busy.value=false;emit('busy',false)}}
const location=(d:Device)=>{const state=preview.value?.state;return (state?.modules.find(m=>m.id===d.moduleId)?.name||'')+' / '+(d.rackId?(state?.racks.find(r=>r.id===d.rackId)?.name||'')+' U'+d.startU:'待上架')};
function exportPreview(){if(!preview.value)return;const cell=(v:unknown)=>{let text=String(v??'');if(/^[\s]*[=+@-]/.test(text))text="'"+text;return '"'+text.replaceAll('"','""')+'"'};const text=['资产编号,设备名称,机位,待处理原因',...preview.value.rows.map(row=>[row.device.assetTag,row.device.name,location(row.device),row.reason].map(cell).join(','))].join('\n');download('初始化预览.csv','\ufeff'+text,'text/csv')}
function downloadAll(){download('初始化设备总清单.csv','\ufeff'+deviceTemplate,'text/csv')}
destinationChanged();
</script>
<template><div class="initialization-wizard guided-initialization">
 <template v-if="done"><div class="init-complete"><div class="complete-check"><Check :size="32"/></div><h2 ref="heading" tabindex="-1">初始化完成</h2><p>{{done.siteName}} · {{done.devices}} 台设备 · {{done.links}} 条连接</p><p v-if="done.pending" class="amber-text">{{done.pending}} 台设备待上架，可进入机房处理。</p><div class="completion-actions"><button class="primary" @click="emit('finish','room',done.projectId,done.siteId)"><Building2 :size="17"/>查看机房</button><button class="secondary" @click="emit('finish','topology',done.projectId,done.siteId)"><Network :size="17"/>查看拓扑</button></div></div></template>
 <template v-else><nav class="init-stepper" aria-label="初始化步骤"><button v-for="(name,i) in ['选择目标','导入清单','检查并创建']" :key="name" :disabled="busy||i>stage" :aria-current="i===stage?'step':undefined" @click="step(i)"><b>{{i+1}}</b>{{name}}</button></nav>
 <h2 ref="heading" tabindex="-1" class="init-step-title">{{stage===0?'在哪里建立机房？':stage===1?'导入清单或只创建布局': '检查本次创建内容'}}</h2>
 <div v-if="error" class="error-banner" role="alert">{{error}}</div>
 <template v-if="stage===0"><div class="form-grid"><label>项目<select v-model="form.projectId" aria-label="初始化项目" @change="form.siteId='';destinationChanged()"><option v-for="p in state.projects" :key="p.id" :value="p.id">{{p.name}}</option><option value="">＋ 新建项目</option></select></label><label v-if="!form.projectId">新项目名称<input v-model="form.projectName" maxlength="80" placeholder="例如：数据中心一期"/></label><label>目标机房<select v-model="form.siteId" aria-label="初始化目标机房" @change="destinationChanged"><option value="">创建新机房</option><option v-for="r in rooms" :key="r.id" :value="r.id">{{r.name}}</option></select></label><label v-if="!form.siteId">新机房名称<input v-model="form.siteName" maxlength="80" placeholder="输入机房名称"/></label></div><p class="single-hint">已有项目和机房可直接选用。</p><div class="modal-actions"><span></span><button class="primary" :disabled="!canNext||busy" @click="step(1)">下一步：导入清单 <ArrowRight :size="16"/></button></div></template>
 <template v-else-if="stage===1"><div class="init-mode-tabs" role="group" aria-label="初始化录入方式"><button class="secondary" :aria-pressed="mode==='unified'" @click="mode='unified';preview=null">设备总清单</button><button class="secondary" :aria-pressed="mode==='modules'" @click="mode='modules';preview=null">分模块上传</button><button class="secondary" :aria-pressed="mode==='layout'" @click="mode='layout';preview=null">只创建布局</button></div><div class="init-target-strip"><span>{{destination}}</span><button class="text-button" @click="step(0)">更换目标</button></div>
 <template v-if="mode==='unified'"><label class="upload-zone init-main-upload"><FileSpreadsheet :size="35"/><strong>{{fileNames.unified||'选择设备总清单 CSV'}}</strong><span>必填：型号、数量；多个模块放在同一张表</span><input type="file" accept=".csv,text/csv" aria-label="上传设备总清单" :disabled="busy" @change="file($event,'unified')"/></label><div class="init-download-row"><button class="secondary" @click="downloadAll"><Download :size="15"/>下载填写模板</button><button class="text-button" @click="example">试用示例</button><button v-if="form.unifiedCSV" class="text-button" @click="form.unifiedCSV='';fileNames.unified='';preview=null">清除文件</button></div><p v-if="showSample" class="sample-notice">当前为示例数据，请勿当作真实清单。</p><details class="compact-help"><summary>布局选择</summary><div class="form-grid"><label>新模块默认布局<select v-model="form.defaultTemplateId" aria-label="默认布局模板"><option v-for="t in state.templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>未填模块列时使用<input v-model="form.defaultModuleName" maxlength="80" aria-label="默认模块名称"/></label></div><p>清单中的模块名称与机房已有模块匹配时直接复用；新模块用默认模板，也可逐行填写“布局模板”名称。</p></details></template>
 <template v-else><div class="form-section-heading"><h3>{{mode==='layout'?'从模板创建模块布局':'分模块导入'}}</h3><button class="secondary" :disabled="form.modules.length>=8" @click="form.modules.push(fresh(form.modules.length+1))"><Plus :size="14"/>增加模块</button></div><article v-for="(row,i) in form.modules" :key="i" class="init-module-card"><div class="init-module-number">{{i+1}}<button v-if="form.modules.length>1" class="icon-button" @click="form.modules.splice(i,1)" aria-label="移除初始化模块"><Trash2 :size="14"/></button></div><div class="form-grid"><label>模块<select v-model="row.moduleId" :aria-label="`第${i+1}模块创建方式`"><option value="">从模板新建</option><option v-for="m in existingModules" :key="m.id" :value="m.id">{{m.name}}</option></select></label><label v-if="!row.moduleId">模板<select v-model="row.templateId" :aria-label="`第${i+1}模块布局模板`"><option v-for="t in state.templates" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label v-if="!row.moduleId">模块名称<input v-model="row.name" maxlength="80"/></label></div><label v-if="mode==='modules'" class="button secondary file-button"><Upload :size="14"/>{{row.fileName||'上传模块CSV'}}<input type="file" accept=".csv" :aria-label="`上传第${i+1}模块设备CSV`" @change="file($event,'unified',row)"/></label></article></template>
 <details class="compact-help"><summary>补充网络与连线（可选）</summary><div class="optional-sheet-row"><div><strong>网络参数</strong><small>VLAN、网段、网关、父子网络</small></div><label class="button secondary file-button">{{fileNames.networks||'上传网络CSV'}}<input type="file" accept=".csv" aria-label="上传网络CSV" @change="file($event,'networks')"/></label><button class="text-button" @click="download('网络参数清单.csv','\ufeff'+networkTemplate,'text/csv')">模板</button><button v-if="form.networksCSV" class="text-button" @click="form.networksCSV='';fileNames.networks=''">清除</button></div><div class="optional-sheet-row"><div><strong>已知连接</strong><small>固定资产编号引用两端设备</small></div><label class="button secondary file-button">{{fileNames.links||'上传连接CSV'}}<input type="file" accept=".csv" aria-label="上传连接CSV" @change="file($event,'links')"/></label><button class="text-button" @click="download('连接清单.csv','\ufeff'+linkTemplate,'text/csv')">模板</button><button v-if="form.linksCSV" class="text-button" @click="form.linksCSV='';fileNames.links=''">清除</button></div><label class="checkbox-label"><input v-model="form.infer" type="checkbox"/>按设备角色生成待确认逻辑连接</label><p>实际端口、速率和网络成员不自动猜测。</p></details>
 <details class="compact-help"><summary>其他选项与帮助</summary><button class="text-button" @click="download('完整字段设备总清单.csv','\ufeff'+fullTemplate,'text/csv')">下载完整字段模板（机位 / 新型号）</button><label class="checkbox-label"><input v-model="form.allowNewModels" type="checkbox"/>按清单中的角色和U高注册新型号</label><p>未知型号必须填写“设备角色”；U高可空，保留待上架。已有型号参数冲突会报错，不覆盖。</p><p>固定资产编号、已知机柜/U位可直接填写；数量大于1时单台IP/SN/编号/U位须留空。设备清单中的“网络”可用分号分隔。</p><p>UTF-8 CSV，合计2MiB，最多8模块/2000设备。可用Excel或WPS填写后另存为CSV UTF-8。相同模块已导入过的相同文件会被拦截，固定资产编号和SN也会检查重复。</p></details>
 <div class="modal-actions"><button class="secondary" :disabled="busy" @click="step(0)">上一步</button><button class="primary" :disabled="busy||!canPreview" @click="inspect">{{busy?'正在检查…':'预览初始化'}} <ArrowRight :size="16"/></button></div></template>
 <template v-else-if="preview&&validPreview"><div class="init-result-metrics"><div><strong>{{preview.newModules}}</strong><span>新模块</span></div><div><strong>{{preview.devices}}</strong><span>设备</span></div><div><strong>{{preview.networks}}</strong><span>新网络</span></div><div><strong>{{preview.links}}</strong><span>新连接</span></div></div><div class="resolved-modules"><span v-for="m in preview.resolvedModules" :key="m.id">{{m.name}} <b>{{m.existing?'复用':'新建'}}</b></span></div><p class="init-result-line">已分配 {{preview.placed}} 台 · 待上架 {{preview.pending}} 台<span v-if="preview.newModels"> · 新型号 {{preview.newModels}} 个</span></p><div v-if="preview.warnings.length" class="attention-summary"><strong>{{preview.warnings.length}} 项需要后续确认</strong><span>{{preview.warnings[0]}}</span></div><details class="compact-help"><summary>检查设备与机位（{{preview.devices}}台）</summary><p class="preview-count">显示前 {{Math.min(100,preview.rows.length)}} 条，共 {{preview.rows.length}} 条设备记录；下载可查看全部。</p><button class="text-button" @click="exportPreview">下载全部机位预览</button><div class="preview-table"><table><thead><tr><th>设备</th><th>资产编号</th><th>位置</th></tr></thead><tbody><tr v-for="row in preview.rows.slice(0,100)" :key="row.device.id"><td>{{row.device.name}}</td><td>{{row.device.assetTag}}</td><td>{{location(row.device)}}</td></tr></tbody></table></div></details><details v-if="preview.warnings.length" class="compact-help"><summary>查看待确认事项</summary><ul><li v-for="(warning,i) in preview.warnings" :key="i">{{warning}}</li></ul></details><details class="compact-help"><summary>检查网络与连接</summary><p class="preview-count">新增连接显示前 {{Math.min(100,newLinks.length)}} 条，共 {{newLinks.length}} 条。</p><button class="text-button" @click="exportLinks">下载全部连接预览</button><div v-if="changedNetworks.length" class="preview-table"><table><thead><tr><th>网络</th><th>VLAN</th><th>网段 / 网关</th></tr></thead><tbody><tr v-for="n in changedNetworks" :key="n.id"><td>{{n.name}}</td><td>{{n.vlan||'待确认'}}</td><td>{{n.cidr||'待确认'}} / {{n.gateway||'待确认'}}</td></tr></tbody></table></div><div class="preview-table"><table><thead><tr><th>端点A</th><th>端点B</th><th>状态</th></tr></thead><tbody><tr v-for="l in newLinks.slice(0,100)" :key="l.id"><td>{{preview.state.devices.find(d=>d.id===l.sourceId)?.name}}</td><td>{{preview.state.devices.find(d=>d.id===l.targetId)?.name}}</td><td>{{l.status==='confirmed'?'已确认':'待确认'}} · {{l.kind==='physical'?'物理':'逻辑'}}</td></tr></tbody></table></div></details><div class="modal-actions"><button class="secondary" :disabled="busy" @click="step(1)">返回调整</button><button class="primary" :disabled="busy" @click="commit"><Check :size="16"/>{{busy?'正在创建…':'确认创建'}}</button></div></template>
 <div v-else class="error-banner" role="alert">输入或数据已变化，请返回导入重新预览。<button class="secondary" @click="step(1)">返回导入</button></div>
 </template>
</div></template>
